CREATE TABLE `pasajeros` (`id_pasajero` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pasajero`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `clases_ruta` (`id_clase_ruta` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_clase_ruta`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `trayectos` (`id_trayecto` INT NOT NULL AUTO_INCREMENT, `id_clase_ruta` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `precio_boleto` DECIMAL(11,2) NOT NULL, `asientos` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_trayecto`), KEY `idx_recurso_categoria` (`id_clase_ruta`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_clase_ruta`) REFERENCES `clases_ruta` (`id_clase_ruta`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `terminales` (`id_terminal` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_terminal`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `conductores` (`id_conductor` INT NOT NULL AUTO_INCREMENT, `id_terminal` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_conductor`), KEY `idx_empleado_sede` (`id_terminal`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_terminal`) REFERENCES `terminales` (`id_terminal`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `viajes_reservados` (`id_viaje_reservado` INT NOT NULL AUTO_INCREMENT, `id_pasajero` INT NOT NULL, `id_conductor` INT NOT NULL, `id_terminal` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_viaje_reservado`), KEY `idx_operacion_persona` (`id_pasajero`), KEY `idx_operacion_empleado` (`id_conductor`), KEY `idx_operacion_sede` (`id_terminal`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_pasajero`) REFERENCES `pasajeros` (`id_pasajero`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_conductor`) REFERENCES `conductores` (`id_conductor`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_terminal`) REFERENCES `terminales` (`id_terminal`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `tramos_reservados` (`id_tramo_reservado` INT NOT NULL AUTO_INCREMENT, `id_viaje_reservado` INT NOT NULL, `id_trayecto` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_tramo_reservado`), KEY `idx_detalle_operacion` (`id_viaje_reservado`), KEY `idx_detalle_recurso` (`id_trayecto`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_viaje_reservado`) REFERENCES `viajes_reservados` (`id_viaje_reservado`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_trayecto`) REFERENCES `trayectos` (`id_trayecto`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_viaje` (`id_pago_viaje` INT NOT NULL AUTO_INCREMENT, `id_viaje_reservado` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_viaje`), KEY `idx_pago_operacion` (`id_viaje_reservado`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_viaje_reservado`) REFERENCES `viajes_reservados` (`id_viaje_reservado`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `reportes_viaje` (`id_reporte_viaje` INT NOT NULL AUTO_INCREMENT, `id_viaje_reservado` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_reporte_viaje`), KEY `idx_evento_operacion` (`id_viaje_reservado`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_viaje_reservado`) REFERENCES `viajes_reservados` (`id_viaje_reservado`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
